import { NextResponse } from "next/server";
import {
  isWorkOSAuthConfigured,
  passwordMatches,
  WORKOS_SESSION_COOKIE,
  workOSSessionValue,
} from "@/app/lib/workos-auth";

export async function POST(request: Request) {
  if (!isWorkOSAuthConfigured()) {
    return NextResponse.redirect(new URL("/login?setup=1", request.url), 303);
  }

  const form = await request.formData();
  const password = String(form.get("password") || "");
  if (!await passwordMatches(password)) {
    return NextResponse.redirect(new URL("/login?error=1", request.url), 303);
  }

  const session = await workOSSessionValue();
  if (!session) {
    return NextResponse.redirect(new URL("/login?setup=1", request.url), 303);
  }

  const response = NextResponse.redirect(new URL("/", request.url), 303);
  response.cookies.set({
    name: WORKOS_SESSION_COOKIE,
    value: session,
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "strict",
    path: "/",
    maxAge: 60 * 60 * 24 * 30,
  });
  return response;
}

import { NextResponse } from "next/server";
import { WORKOS_SESSION_COOKIE } from "@/app/lib/workos-auth";

export async function POST(request: Request) {
  const response = NextResponse.redirect(new URL("/login", request.url), 303);
  response.cookies.set({
    name: WORKOS_SESSION_COOKIE,
    value: "",
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "strict",
    path: "/",
    maxAge: 0,
  });
