-footer button svg { width: 11px; }.capacity-note { position: sticky; top: 22px; padding: 22px; border: 1px solid #38432d; border-radius: 17px; background: #1a2117; }.capacity-note > svg { width: 24px; color: #b7ff4a; }.capacity-note > span { display: block; margin-top: 25px; color: #b7ff4a; font-size: 8px; font-weight: 900; letter-spacing: .13em; }.capacity-note h2 { margin: 10px 0 12px; font-size: 20px; line-height: 1.15; letter-spacing: -.04em; }.capacity-note p { color: #9ca79f; font-size: 11px; line-height: 1.55; }.capacity-note button { margin-top: 16px; display: flex; align-items: center; gap: 5px; border: 0; background: none; color: #b7ff4a; font-size: 9px; font-weight: 900; }.capacity-note button svg { width: 13px; }

