gin: 0; display: flex; flex-direction: column; gap: 4px; color: #aeb7b1; font-size: 9px; }.timeline-callout p strong { color: #f2f5f3; font-size: 10px; }.timeline-callout button { display: flex; align-items: center; border: 0; background: none; color: #f2bc72; font-size: 8px; font-weight: 900; }.timeline-callout button svg { width: 12px; }

