data-slot="select-trigger"] { width: 100%; }.quick-form input { min-width: 0; height: 39px; padding: 0 12px; border: 1px solid #303a34; border-radius: 9px; outline: none; background: #101411; color: #f2f5f3; }.quick-form input:focus { border-color: #b7ff4a; }

