.deadline-ribbon { margin-top: auto; padding: 10px; border-top: 1px solid #29312d; display: grid; gap: 5px; background: #101411; }.deadline-ribbon > span { display: flex; align-items: center; gap: 5px; margin-bottom: 2px; color: #ff9f43; font-size: 7px; font-weight: 900; letter-spacing: .1em; }.deadline-ribbon > span svg { width: 11px; }.deadline-ribbon button { min-height: 26px; padding: 0 7px; display: flex; align-items: center; gap: 7px; border: 0; border-radius: 7px; background: transparent; color: #8d9991; font-size: 8px; text-align: left; }.deadline-ribbon button:hover { background: #1b211e; color: #edf2ef; }.deadline-ribbon b { color: #eef2ef; font-size: 8px; }
.team-roster { display: flex; min-height: 100%; flex-direction: column; }.roster-head > svg { width: 17px; color: #b7ff4a; }.roster-list { padding: 7px; overflow-y: auto; }
.roster-person { min-height: 51px; display: grid; grid-template-columns: 34px minmax(0, 1fr) 8px 14px; gap: 8px; align-items: center; padding: 6px 7px; border: 1px solid transparent; border-radius: 10px; cursor: grab; }.roster-person:hover { border-color: #354038; background: #19201c; }.roster-person:active { cursor: grabbing; }.roster-person .avatar { width: 32px; height: 32px; border-radius: 9px; font-size: 8px; }.roster-person > span { min-width: 0; display: flex; flex-direction: column; gap: 3px; }.roster-person strong, .roster-person small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.roster-person strong { font-size: 9px; }.roster-person small { color: #748078; font-size: 7px; }.roster-person > i { width: 7px; height: 7px; border-radius: 50%; }.roster-person > i.hot { background: #ff6376; box-shadow: 0 0 0 3px #ff637614; }.roster-person > i.warm { background: #ffad4f; }.roster-person > i.cool { background: #67d891; }.roster-person > svg { width: 13px; color: #525d56; }
