.account-dock-track { display: flex; min-width: 0; gap: 7px; overflow-x: auto; scrollbar-width: none; }.account-dock-track::-webkit-scrollbar { display: none; }
.account-dock-chip { position: relative; min-width: 135px; height: 49px; padding: 6px 8px; display: grid; grid-template-columns: 29px 1fr; gap: 7px; align-items: center; border: 1px solid #2c3530; border-radius: 10px; background: #171c19; color: #edf2ef; text-align: left; overflow: hidden; }.account-dock-chip:hover, .account-dock-chip.ready:hover { border-color: var(--account-color); background: #1c231f; }.account-dock-chip.ready { border-style: dashed; }.account-dock-chip > span { min-width: 0; display: flex; flex-direction: column; gap: 2px; }.account-dock-chip strong, .account-dock-chip small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.account-dock-chip strong { font-size: 8px; }.account-dock-chip small { color: #748078; font-size: 7px; }.account-dock-chip > i { position: absolute; inset: auto 0 0; height: 2px; background: var(--account-color); }
.account-card.is-drop-ready { border-style: dashed; }.account-card.is-drop-ready:hover { border-color: var(--account-color); box-shadow: 0 0 0 3px color-mix(in srgb, var(--account-color) 12%, transparent); }
