  .page-heading h1 { font-size: 30px; }.page-heading p { display: none; }.top-actions { flex-wrap: wrap; }.search-box { min-width: 190px; }.accounts-grid { grid-template-columns: 1fr; }.metric-strip small { display: none; }.metric-strip article { display: flex; flex-direction: column; align-items: flex-start; justify-content: center; }.dashboard-grid { display: block; }.panel { margin-bottom: 12px; }
}

/* Compact viewport: one operational screen, no page-level scroll. */
