.dashboard-view .metric-strip strong { font-size: 30px; line-height: 1; }
.dashboard-view .metric-strip small { font-size: 9px; }
.control-room { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 258px; gap: 11px; margin: 0; align-items: stretch; overflow: hidden; }
.dashboard-workbench { min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1.18fr) minmax(320px, .82fr); gap: 11px; }
.ops-panel, .team-roster, .account-dock { min-height: 0; border-radius: 14px; }
.ops-panel { display: flex; flex-direction: column; }
.ops-head, .roster-head { min-height: 52px; height: 52px; flex: none; padding: 10px 14px; }
