.mini-task-board { min-height: 0; flex: 1; display: grid; grid-template-columns: repeat(3, minmax(145px, 1fr)); gap: 7px; padding: 8px; overflow: hidden; }
.mini-task-lane { min-width: 0; min-height: 0; height: 100%; padding: 7px; overflow: hidden; }
.mini-task-lane .work-card h3 { margin: 10px 0 5px; font-size: 12px; }
.mini-task-lane .work-card > p { font-size: 8.5px; }
.lane-more { width: 100%; height: 25px; margin-top: 6px; border: 1px dashed #303934; border-radius: 7px; background: transparent; color: #819087; font-size: 8px; font-weight: 850; }
.lane-more:hover { color: #b7ff4a; border-color: #b7ff4a66; }
.project-overview-list { min-height: 0; flex: 1; padding: 5px 10px; overflow: hidden; }
.dashboard-project { min-height: 51px; padding-block: 6px; }
.dashboard-project-copy strong { font-size: 11px; }
.dashboard-project-copy small { color: #819087; font-size: 7.5px; }
.deadline-ribbon { padding: 8px 10px; gap: 3px; }
.deadline-ribbon > span { margin-bottom: 1px; }
.deadline-ribbon button { min-height: 22px; color: #929e96; }
.team-roster { min-height: 0; height: 100%; }
.roster-list { min-height: 0; flex: 1; padding: 6px; overflow: hidden; }
.roster-person { min-height: 44px; height: calc(12.5% - 1px); grid-template-columns: 31px minmax(0, 1fr) 8px 14px; padding: 4px 6px; }
.roster-person .avatar { width: 30px; height: 30px; border-radius: 8px; }
