.roster-person small { color: #7e8a82; font-size: 7.5px; }
.roster-footer { min-height: 36px; height: 36px; flex: none; color: #a4aea8; font-size: 8.5px; }
.account-dock { height: 62px; margin: 0; padding: 7px 9px; }
.account-dock-chip { min-width: 138px; height: 46px; padding-block: 5px; }
.account-dock-chip strong { font-size: 9px; }
.account-dock-chip small { color: #7f8b83; font-size: 7.5px; }

@media (min-width: 921px) and (max-width: 1180px) {
  .os-shell { grid-template-columns: 184px minmax(0, 1fr); }
  .sidebar-shell { padding-inline: 12px; }
  .brand-lockup { justify-content: flex-start; padding-inline: 7px; }
  .brand-lockup strong, .nav-item span { display: block; }
  .nav-section-label { display: flex; }
  .sync-card div, .user-chip div { display: flex; }
  .nav-item { justify-content: flex-start !important; padding: 0 11px !important; }
  .sync-card, .user-chip { justify-content: flex-start; }
  .user-chip { padding-inline: 8px; }
  .control-room { grid-template-columns: minmax(0, 1fr) 226px; }
  .dashboard-workbench { grid-template-columns: minmax(0, 1.1fr) minmax(280px, .9fr); }
  .dashboard-project { grid-template-columns: 29px minmax(0, 1fr) auto 15px; }
  .dashboard-project .people-stack { display: none; }
  .mini-task-lane { min-height: 0; }
}

@media (min-width: 921px) and (max-width: 1040px) {
  .control-room { grid-template-columns: minmax(0, 1fr) 210px; }
  .dashboard-workbench { grid-template-columns: 1fr; }
  .projects-overview { display: none; }
}

@media (max-width: 920px) and (min-width: 761px) {
  .nav-section-label, .nav-item small { display: none; }
  .control-room { grid-template-columns: minmax(0, 1fr) 210px; }
  .dashboard-workbench { grid-template-columns: 1fr; }
  .projects-overview { display: none; }
  .mini-task-lane { min-height: 0; }
}

@media (max-width: 760px) {
  html, body { height: auto; min-height: 100%; overflow: auto; }
  .os-shell { height: auto; min-height: 100vh; overflow: visible; }
  .sidebar-shell { min-height: 66px; }
  .nav-section-label { display: none; }
  .nav-list { grid-auto-rows: 50px !important; }
  .nav-item { height: 50px !important; min-height: 50px !important; margin: 0 !important; }
  .nav-item small { display: none; }
  .nav-dashboard { background: transparent !important; border-color: transparent !important; }
  .nav-dashboard[data-state="active"] { color: #f7f9f8 !important; background: #202722 !important; border-color: #303b35 !important; box-shadow: inset 0 3px #b7ff4a !important; }
  .main-stage { height: auto; min-height: 100vh; display: block; overflow: visible; }
  .topbar { height: auto; }
  .view-content { height: auto; overflow: visible; }
  .dashboard-view { display: block; }
  .control-room { display: block; margin-top: 12px; overflow: visible; }
  .dashboard-workbench { display: block; }
  .projects-overview { display: flex; }
  .team-roster { height: auto; }
  .roster-list { overflow: visible; }
  .roster-person { height: auto; }
  .account-dock { height: auto; margin-top: 12px; }
}

/* Evaluation + real people intelligence */
.priority-none { background: #b8c0b8 !important; }
.project-board-complete { grid-template-columns: repeat(8, minmax(238px, 1fr)); min-width: 1940px; }
