.people-summary svg { width: 18px; color: #434943; }.people-summary span { color: #687169; font-size: 9px; line-height: 1.25; }.people-summary b { display: block; color: #252b25; font-size: 18px; }
.people-summary > div { flex-direction: column; align-items: flex-start; justify-content: center; gap: 3px; }.people-summary > div strong { font-size: 11px; }.people-summary > div small { color: #7e877f; font-size: 8.5px; }
