.ratio-chip { min-width: 48px; height: 35px; padding: 0 7px; display: inline-flex; align-items: baseline; justify-content: center; border-radius: 10px; background: #dce978; color: #252b25; font-size: 16px; font-weight: 800; }
.ratio-chip small { margin-left: 2px; font-size: 7px; }.ratio-chip.empty { background: #eef0ed; color: #909790; }
.profile-metrics { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; }
.profile-metrics span { padding: 7px; border-radius: 8px; background: #f4f6f2; color: #858d86; font-size: 7.5px; }.profile-metrics b { display: block; color: #363c36; font-size: 12px; }
.employee-card .load-row, .employee-card > [data-slot="progress"], .employee-card .team-footer { grid-column: 1 / -1; }
.employee-card .team-footer { width: 100%; }.employee-card .team-footer > span:last-child { display: flex; align-items: center; gap: 3px; color: #cb373d; }.employee-card .team-footer svg { width: 11px; }
.data-health-card { position: static !important; height: 100%; overflow: hidden; }
