.data-health-card li { display: flex; gap: 7px; align-items: center; color: #697169; font-size: 9px; }.data-health-card li svg { width: 13px; flex: none; color: #67b883; }.data-health-card li:nth-last-child(-n+2) svg { color: #ef3f43; }

.sheet-actions-stacked { display: grid !important; gap: 8px; }.sheet-actions-stacked > div { display: grid; grid-template-columns: 1fr auto; gap: 8px; }
.close-evaluate-button { background: var(--ogilvy-red) !important; color: #fff !important; box-shadow: 0 7px 18px #ef3f4322; }.close-evaluate-button:hover { background: #d9343a !important; }.close-evaluate-button svg { width: 15px; }
.employee-sheet { width: min(720px, 94vw) !important; max-width: 720px !important; }
