.employee-kpis span { color: #7b847c; font-size: 7.5px; font-weight: 850; letter-spacing: .08em; }.employee-kpis strong { display: block; margin: 6px 0 2px; color: #282e28; font-size: 23px; letter-spacing: -.04em; }.employee-kpis strong small { font-size: 8px; }.employee-kpis p { color: #858d86; font-size: 8px; }
.employee-section { padding: 14px; border: 1px solid #e2e7df; border-radius: 14px; background: #fff; }
.employee-section-title { display: flex; align-items: center; gap: 9px; }.employee-section-title > svg { width: 18px; color: var(--ogilvy-red); }.employee-section-title span { color: #919a92; font-size: 7.5px; font-weight: 850; letter-spacing: .1em; }.employee-section-title h3 { color: #2c322c; font-size: 13px; font-weight: 700; }
.workload-big { margin-top: 13px; display: grid; grid-template-columns: 62px 1fr; gap: 14px; align-items: center; }.workload-big > strong { font-size: 25px; }.workload-big > div { display: grid; gap: 7px; }.workload-big span { color: #7b847c; font-size: 9px; }
.rating-distribution { margin-top: 13px; display: grid; gap: 6px; }.rating-distribution > div { display: grid; grid-template-columns: 30px 1fr 22px; gap: 8px; align-items: center; }.rating-distribution span { display: flex; align-items: center; gap: 2px; color: #6f776f; font-size: 9px; }.rating-distribution span svg { width: 9px; fill: #efb631; color: #efb631; }.rating-distribution i { height: 6px; border-radius: 99px; background: #edf0eb; overflow: hidden; }.rating-distribution i b { display: block; height: 100%; border-radius: inherit; background: #efb631; }.rating-distribution strong { font-size: 9px; }.history-caption { margin-top: 10px; color: #8a928b; font-size: 8.5px; }
.dimension-profile { margin-top: 13px; display: grid; gap: 8px; }.dimension-profile > div { display: grid; grid-template-columns: 118px 1fr 28px; gap: 9px; align-items: center; }.dimension-profile > div > span { color: #515a52; font-size: 9px; font-weight: 750; }.dimension-profile small { display: block; margin-top: 2px; color: #969e97; font-size: 7px; font-weight: 500; }.dimension-profile i { height: 7px; overflow: hidden; border-radius: 99px; background: #edf0eb; }.dimension-profile i b { display: block; height: 100%; border-radius: inherit; background: var(--ogilvy-ink); }.dimension-profile strong { font-size: 10px; text-align: right; }
