.session-signals { margin-top: 13px; padding-top: 11px; border-top: 1px solid #e8ece6; }.session-signals > span { color: #929a93; font-size: 7.5px; font-weight: 850; letter-spacing: .08em; }.session-signals .tag-cloud b.negative { background: #f5dfe4; color: #813a49; }
.data-gaps { background: #fff8f8; border-color: #f0dada; }.data-gaps ul { margin: 12px 0 0; display: grid; grid-template-columns: 1fr 1fr; gap: 7px 20px; padding-left: 16px; color: #7e5558; font-size: 8.5px; }

.evaluation-dialog { width: min(690px, 94vw) !important; max-width: 690px !important; max-height: 91vh; overflow: hidden; }
.evaluation-body { min-height: 0; display: grid; gap: 15px; overflow-y: auto; padding-right: 4px; }
.score-question { padding: 14px; display: grid; grid-template-columns: 120px 1fr auto; gap: 12px; align-items: center; border-radius: 14px; background: #f2f4ef; }.score-question > span { font-size: 12px; font-weight: 750; }.score-question > strong { color: #8a928b; font-size: 10px; }
