.dimension-rubric { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; padding: 10px; border-radius: 13px; background: #f6f7f3; }.dimension-rubric > div { min-height: 48px; padding: 7px 9px; display: flex; align-items: center; justify-content: space-between; gap: 8px; border: 1px solid #e3e7df; border-radius: 10px; background: #fff; }.dimension-rubric > div > span { min-width: 0; display: grid; gap: 2px; }.dimension-rubric strong { color: #3b423b; font-size: 9px; }.dimension-rubric small { color: #929a93; font-size: 7px; }
.star-picker { display: flex; gap: 5px; }.star-picker button { width: 36px; height: 36px; display: grid; place-items: center; border: 0; border-radius: 9px; background: #fff; color: #c8cec6; }.star-picker button:hover { color: #efb631; transform: translateY(-1px); }.star-picker button.active { background: #fff3c8; color: #e8aa14; }.star-picker svg { width: 19px; }.star-picker button.active svg { fill: currentColor; }.star-picker.compact { gap: 2px; }.star-picker.compact button { width: 25px; height: 25px; border-radius: 6px; }.star-picker.compact svg { width: 12px; }
.evaluation-label { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 7px; }.evaluation-label > span { color: #3b413b; font-size: 10px; font-weight: 750; }.evaluation-label small { color: #8e968f; font-size: 8px; }.evaluation-label label { display: flex; align-items: center; gap: 8px; }
.signal-picker { display: flex; flex-wrap: wrap; gap: 5px; }.signal-picker button { min-height: 28px; padding: 0 9px; display: flex; align-items: center; gap: 4px; border: 1px solid #e0e5de; border-radius: 8px; background: #fff; color: #6d756e; font-size: 8.5px; }.signal-picker button svg { width: 11px; }.signal-good button.active { border-color: #bdd696; background: #eef4bd; color: #4e5d31; }.signal-bad button.active { border-color: #e9bfc8; background: #f8e1e6; color: #823c4a; }
