/* Ogilvy Soft System — SF typography, editorial colour, friendlier surfaces */
:root {
  --background: #f2f4ef; --foreground: #20251f; --card: #ffffff; --card-foreground: #20251f;
  --popover: #ffffff; --popover-foreground: #20251f; --primary: #ef3f43; --primary-foreground: #ffffff;
  --secondary: #eef1ea; --secondary-foreground: #252b25; --muted: #edf0ea; --muted-foreground: #768077;
  --accent: #e8eddd; --accent-foreground: #20251f; --destructive: #d92f3f; --border: #dfe5dc;
  --input: #d9e0d7; --ring: #ef3f43; --ogilvy-red: #ef3f43; --ogilvy-lime: #dce978;
  --ogilvy-pink: #e7bdc8; --ogilvy-ink: #2f2c67; --ogilvy-paper: #f2f4ef;
}
html, body { background: var(--ogilvy-paper); color: var(--foreground); }
body { font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Arial, sans-serif; font-size: 14px; }
button, input { letter-spacing: -.01em; }
* { scrollbar-color: #c8cec5 transparent; scrollbar-width: thin; }

.os-shell { grid-template-columns: 216px minmax(0, 1fr); background: var(--ogilvy-paper); }
.sidebar-shell { padding: 22px 15px 16px; border-right: 1px solid #e1e6de; background: #fbfcf9; }
.brand-lockup { padding-bottom: 27px; }
.brand-lockup > span { width: 39px; height: 39px; border-radius: 12px; background: var(--ogilvy-red); color: #fff; transform: none; box-shadow: 0 7px 18px #ef3f4328; font-family: Georgia, serif; font-size: 24px; font-weight: 700; }
.brand-lockup strong { color: #20251f; font-size: 12px; line-height: 1; letter-spacing: .1em; }
.nav-section-label { color: #9aa39a; }
.nav-section-label small { color: #b1b8b1; }
.nav-list { gap: 5px !important; }
.nav-item { color: #707970 !important; font-size: 12.5px !important; font-weight: 650 !important; }
.nav-item:hover { color: #222922 !important; background: #f0f3ed !important; }
.nav-item[data-state="active"] { color: #252b25 !important; border-color: #d7df9c !important; background: var(--ogilvy-lime) !important; box-shadow: none !important; }
.nav-item[data-state="active"] svg { color: var(--ogilvy-red); }
.nav-dashboard { background: #f5f7f2 !important; border-color: #e7ebe4 !important; }
.nav-dashboard[data-state="active"] { color: #252b25 !important; background: var(--ogilvy-lime) !important; border-color: #d7df9c !important; }
.nav-dashboard[data-state="active"] > small { color: #747b3a; }
.sync-card { border-color: #e2e7df; background: #fff; box-shadow: 0 4px 15px #3143310a; }
.sync-dot { background: #70c995; box-shadow: 0 0 0 4px #70c9951f; }
.sync-card strong, .user-chip strong { color: #283029; }
.sync-card small, .user-chip small { color: #929b93; }
.user-chip > span { background: var(--ogilvy-pink); color: #4c2430; }

.main-stage { background: var(--ogilvy-paper); }
.topbar { height: 106px; border-bottom: 0; padding: 17px 26px; background: #fbfcf9; box-shadow: 0 1px 0 #e4e8e1; }
.page-heading > span, .panel-head > div > span, .holiday-head > div > span { color: #969f97; font-size: 9px; letter-spacing: .12em; }
.page-heading h1 { margin: 5px 0 4px; color: #20251f; font-family: inherit; font-size: clamp(27px, 2.2vw, 35px); font-weight: 730; letter-spacing: -.042em; line-height: 1.05; }
.page-heading p { color: #7b847c; font-size: 12.5px; }
.search-box { border-color: #e0e5dd; background: #fff; color: #929a93; box-shadow: 0 3px 12px #2f392f08; }
.search-box input { color: #252b25; }
.search-box:focus-within { border-color: #ef3f4380; box-shadow: 0 0 0 3px #ef3f4312; }
.draft-chip { border-color: #e6c4c6; background: #fff3f3; color: #c53239; }
.add-button { background: var(--ogilvy-red) !important; color: #fff !important; box-shadow: 0 7px 18px #ef3f4326; }
.add-button:hover { background: #d9343a !important; }
.view-content { padding: 18px 24px 22px; }

.metric-strip { gap: 11px; border: 0; border-radius: 0; overflow: visible; background: transparent; }
.metric-strip article, .dashboard-view .metric-strip article { height: 78px; min-height: 0; padding: 12px 16px; border: 0; border-radius: 15px; box-shadow: 0 8px 24px #2833280c; }
.metric-strip article:nth-child(1) { background: #eef4bd; }
.metric-strip article:nth-child(2) { background: #f3d8df; }
.metric-strip article:nth-child(3) { background: #f9d9d9; }
.metric-strip article:nth-child(4) { background: #dddcef; }
.metric-strip article > span, .dashboard-view .metric-strip article > span { color: #656d65; font-size: 9px; letter-spacing: .1em; }
.metric-strip strong, .dashboard-view .metric-strip strong { color: #20251f; font-size: 28px; font-weight: 740; letter-spacing: -.055em; }
